actions.script:
def p = ec.web.parameters
try {
    if (!p.productId) { ec.web.sendJsonResponse([success:false, error:'Missing product']); return }
    def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameter('moduleId',kitchenModuleId ?: 'pos').call()
    if (access?.canWrite != true) { ec.web.sendJsonResponse([success:false, error:'You cannot change POS prices.']); return }
    def scope = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess')
        .parameter('productId',p.productId).call()
    if (!scope.allowed) {
        ec.message.clearErrors(); ec.web.sendJsonResponse([success:false, error:'You do not have access to this product.']); return
    }
    def posOrg = scope.organizationPartyId
    def rawPrices = new groovy.json.JsonSlurper().parseText((p.modePricesJson ?: '{}').toString())
    if (!(rawPrices instanceof Map) || !rawPrices || rawPrices.size() > 30) { ec.web.sendJsonResponse([success:false, error:'Select at least one editable sales mode.']); return }
    def rawThresholds = new groovy.json.JsonSlurper().parseText((p.modeThresholdsJson ?: '{}').toString())
    if (!(rawThresholds instanceof Map) || rawThresholds.keySet().any { it != 'WHOLESALE' }) { ec.web.sendJsonResponse([success:false, error:'Invalid quantity-break mode.']); return }
    ec.entity.find('mantle.party.Party').condition('partyId',posOrg).disableAuthz().forUpdate(true).one()
    def availableModes = ec.service.sync().name('zenith.pos.PosModeServices.get#OrganizationModes')
        .parameter('organizationPartyId',posOrg).call().modes ?: []
    def byId = availableModes.collectEntries { [(it.salesModeId):it] }
    if (rawPrices.keySet().any { id -> !byId[id] || (id != 'RETAIL' && byId[id].priceSource != 'PpsFixedProduct') }) {
        ec.web.sendJsonResponse([success:false, error:'A selected sales mode cannot be priced for this product.']); return
    }
    if (rawThresholds && !rawPrices.containsKey('WHOLESALE')) { ec.web.sendJsonResponse([success:false, error:'Select Wholesale to set its quantity break.']); return }
    def parsed = [:]
    for (entry in rawPrices) {
        def value = entry.value == null ? '' : entry.value.toString().trim()
        if (value && !(value ==~ /\d+(\.\d{1,2})?/)) { ec.web.sendJsonResponse([success:false, error:'Enter non-negative prices with up to two decimal places.']); return }
        parsed[entry.key] = value ? (value as BigDecimal) : null
    }
    def qtyText = rawThresholds.WHOLESALE == null ? '' : rawThresholds.WHOLESALE.toString().trim()
    if (qtyText && !(qtyText ==~ /\d+/)) { ec.web.sendJsonResponse([success:false, error:'Auto-wholesale quantity must be a non-negative whole number.']); return }
    def threshold = qtyText ? (qtyText as BigDecimal) : null
    if (threshold != null && threshold > 0 && (!parsed.WHOLESALE || parsed.WHOLESALE <= 0)) { ec.web.sendJsonResponse([success:false, error:'Set a Wholesale price before enabling auto-wholesale.']); return }
    // Hidden columns are absent from the request and cannot be changed by this row save.
    parsed.each { id, price ->
        if (id == 'RETAIL' && (price == null || price <= 0)) return
        def args = [productId:p.productId, salesModeId:id, price:price]
        if (id == 'WHOLESALE') args.thresholdQty = threshold
        ec.service.sync().name('zenith.pos.PosServices.set#PosModePrice').parameters(args).call()
    }
    if (!ec.message.hasError()) ec.service.sync().name('zenith.pos.ProductModePricingServices.mark#CatalogChanged')
        .parameter('organizationPartyId',posOrg).disableAuthz().call()
    if (ec.message.hasError()) {
        def em = ec.message.errorsString
        ec.transaction.setRollbackOnly('POS price save failed', new IllegalStateException(em))
        ec.message.clearErrors(); ec.web.sendJsonResponse([success:false, error:em]); return
    }
    def effRetail = parsed.RETAIL
    if (effRetail == null) { def _pr = ec.entity.find('mantle.product.Product').condition('productId',p.productId).one(); effRetail = _pr?.mrpAmount as BigDecimal }
    def warn = null
    if (effRetail != null && effRetail > 0G) {
        def _hi = []
        parsed.each { id, price -> if (id != 'RETAIL' && price != null && price > effRetail) _hi.add((byId[id].modeName ?: id) + ' (₹' + price.stripTrailingZeros().toPlainString() + ')') }
        if (_hi) warn = 'Saved - but ' + _hi.join(' and ') + (_hi.size() > 1 ? ' are' : ' is') + ' higher than Retail (₹' + effRetail.stripTrailingZeros().toPlainString() + '). Please double-check.'
    }
    ec.web.sendJsonResponse([success:true, warning:warn])
} catch (Exception e) {
    ec.transaction.setRollbackOnly('POS price save failed', e)
    ec.web.sendJsonResponse([success:false, error:e.message])
}

def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').call()
if (!access?.allowed) return
def ids = (ec.web.parameters.modeIds ?: '').toString().split(',').collect { it.trim() }.findAll { it }.unique()
def availableModes = ids && ids.size() <= 100 ? ec.service.sync().name('zenith.pos.PosModeServices.get#OrganizationModes')
    .parameter('organizationPartyId',access.organizationPartyId).call().modes : []
if (!ids || !(availableModes*.salesModeId ?: []).containsAll(ids)) {
    ec.web.sendJsonResponse([success:false,error:'Select at least one available sales mode.']); return
}
ec.user.setPreference('POS_PRODUCT_PRICE_MODES_' + access.organizationPartyId,ids.join(','))
ec.web.sendJsonResponse([success:true])

def p = ec.web.parameters
def _searchTerm = p.searchTerm; def _catId = p.catId; def _pricingStatus = p.pricingStatus; def _gstFilter = p.gstFilter
def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').call()
if (!access.allowed) return
def posOrg = access.organizationPartyId
def availableModes = (ec.service.sync().name('zenith.pos.PosModeServices.get#OrganizationModes')
    .parameter('organizationPartyId',posOrg).call().modes ?: [])
    .sort(false) { it.salesModeId == 'RETAIL' ? 0 : it.salesModeId == 'WHOLESALE' ? 1 : 2 }
def requested = (p.modeIds ?: ec.user.getPreference('POS_PRODUCT_PRICE_MODES_' + posOrg) ?: 'RETAIL,WHOLESALE').toString().split(',').collect { it.trim() }.findAll { it }.unique()
def selectedModes = availableModes.findAll { requested.contains(it.salesModeId) }
if (!selectedModes && availableModes) selectedModes = availableModes.findAll { it.salesModeId in ['RETAIL','WHOLESALE'] } ?: [availableModes[0]]
def catPIds = null
if (_catId) { catPIds = [] as Set; ec.entity.find("mantle.product.category.ProductCategoryMember").condition("productCategoryId", _catId).list().each { catPIds.add(it.productId) } }
def slab = [:]; try { ec.entity.find("zenith.erp.india.IndiaGstSlab").list().each { slab[it.gstSlabId] = it.gstRate } } catch (Exception ig) {}
def rateSlab = { pr -> (pr.gstSlabId && slab[pr.gstSlabId] != null) ? (slab[pr.gstSlabId] as BigDecimal) : null }
def cands = ec.entity.find("mantle.product.Product").condition("productTypeEnumId", "PtAsset")
    .condition("ownerPartyId", posOrg).orderBy("productName").limit(5000).list()
def tl = (_searchTerm ?: '').toLowerCase().trim()
def fl = cands.findAll { pr ->
    (tl == '' || (pr.productName ?: '').toLowerCase().contains(tl) || (pr.pseudoId ?: '').toLowerCase().contains(tl)) &&
    (catPIds == null || catPIds.contains(pr.productId)) &&
    (_pricingStatus != 'with' || (pr.mrpAmount != null && (pr.mrpAmount as BigDecimal) > 0G)) &&
    (_pricingStatus != 'without' || pr.mrpAmount == null || (pr.mrpAmount as BigDecimal) <= 0G) &&
    (!_gstFilter || (rateSlab(pr) != null && rateSlab(pr).stripTrailingZeros().toPlainString() == _gstFilter))
}
def ids = fl.collect { it.productId }
def modePrices = [:]; def wT = [:]
if (ids) { ec.entity.find("zenith.erp.pos.PosProductModePrice").condition("productId", "in", ids).list().each { mp ->
    if (selectedModes.any { it.salesModeId == mp.salesModeId }) modePrices[mp.productId + ':' + mp.salesModeId] = mp.price
    if (mp.salesModeId == 'WHOLESALE') wT[mp.productId] = mp.thresholdQty
} }
def esc = { v -> if (v == null) return ""; String s = v.toString().trim(); (s.contains(",")||s.contains("\"")||s.contains("\n")) ? "\"" + s.replace("\"","\"\"") + "\"" : s }
def bd = { v -> v == null ? "" : (v as BigDecimal).stripTrailingZeros().toPlainString() }
StringBuilder csv = new StringBuilder()
csv.append("ZetaERP - Product Pricing (all prices are BEFORE GST)\n")
csv.append("Generated: ${ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')}\n\n")
def headers = ['#','Product Name','SKU','GST %']
selectedModes.each { m ->
    headers.add((m.modeName ?: m.salesModeId) + ' (Before GST)')
    if (m.salesModeId == 'WHOLESALE') headers.add('Auto-WS Qty')
}
csv.append(headers.collect { esc(it) }.join(',')).append('\n')
int i = 0
fl.each { pr ->
    i++; def rt = rateSlab(pr)
    def cells = [i, pr.productName ?: pr.productId, pr.pseudoId ?: '', rt != null ? rt.stripTrailingZeros().toPlainString()+'%' : '']
    selectedModes.each { m ->
        def override = modePrices[pr.productId + ':' + m.salesModeId]
        def price = override != null ? override : pr.mrpAmount
        if (override == null && m.priceSource == 'PpsDiscountMrp' && price != null) price = (price as BigDecimal) * (1G - ((m.discountPercent ?: 0) as BigDecimal) / 100G)
        cells.add(bd(price))
        if (m.salesModeId == 'WHOLESALE') cells.add(bd(wT[pr.productId]))
    }
    csv.append(cells.collect { esc(it) }.join(',')).append('\n')
}
ec.web.sendTextResponse(csv.toString(), "text/csv", "Product_Pricing_${ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd_HHmm')}.csv")

def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').call()
def posOrg = access.allowed ? access.organizationPartyId : null
priceModeChoices = posOrg ? (ec.service.sync().name('zenith.pos.PosModeServices.get#OrganizationModes')
    .parameter('organizationPartyId',posOrg).call().modes ?: [])
    .sort(false) { it.salesModeId == 'RETAIL' ? 0 : it.salesModeId == 'WHOLESALE' ? 1 : 2 } : []
def requestedIds = (modeIds ?: ec.user.getPreference('POS_PRODUCT_PRICE_MODES_' + posOrg) ?: 'RETAIL,WHOLESALE').toString().split(',').collect { it.trim() }.findAll { it }.unique()
selectedPriceModes = priceModeChoices.findAll { requestedIds.contains(it.salesModeId) }
if (!selectedPriceModes && priceModeChoices) selectedPriceModes = priceModeChoices.findAll { it.salesModeId in ['RETAIL','WHOLESALE'] } ?: [priceModeChoices[0]]
selectedModeIds = selectedPriceModes.collect { it.salesModeId }
selectedModeIdsCsv = selectedModeIds.join(',')
tableColumnCount = 5 + selectedPriceModes.size() + (selectedModeIds.contains('WHOLESALE') ? 1 : 0)
hasEditableSelectedMode = selectedPriceModes.any { it.salesModeId == 'RETAIL' || it.priceSource == 'PpsFixedProduct' }
// Root-relative app base ("/apps" | "/qapps" | "/vapps") for the cross-module "Add Product" link.
def _uri = (ec.web?.request?.requestURI ?: '')
def _zi = _uri.indexOf('/zenith/')
appBase = _zi > 0 ? _uri.substring(0, _zi) : ''
def pageSizeNum = 10
try { if ([10,25,50].contains(pageSize as Integer)) pageSizeNum = pageSize as Integer } catch (Exception ignored) {}
def pIdx = 0
try { if (pageIndex) pIdx = (pageIndex as Integer) } catch (Exception ig) { pIdx = 0 }
if (pIdx < 0) pIdx = 0

categories = posOrg ? ec.entity.find("mantle.product.category.ProductCategory")
    .condition("ownerPartyId", posOrg).orderBy("categoryName").list() : []

// Product ids that belong to the selected category (if filtering).
def catProdIds = null
if (posOrg && catId) {
    catProdIds = [] as Set
    ec.entity.find("mantle.product.category.ProductCategoryMember").condition("productCategoryId", catId).list().each { catProdIds.add(it.productId) }
}

// Load candidate products (tenant-scoped), then filter by search/category in memory.
def candidates = posOrg ? ec.entity.find("mantle.product.Product").condition("productTypeEnumId", "PtAsset")
    .condition("ownerPartyId", posOrg).orderBy("productName").limit(5000).list() : []
// GST slab -> rate map (used by the GST filter, the average-GST stat card, and the rows; cheap, no HSN fallback).
def slabRates = [:]
try { ec.entity.find("zenith.erp.india.IndiaGstSlab").list().each { slabRates[it.gstSlabId] = it.gstRate } } catch (Exception ig) {}
def rateSlabOf = { pr -> (pr.gstSlabId && slabRates[pr.gstSlabId] != null) ? (slabRates[pr.gstSlabId] as BigDecimal) : null }
def termLower = (searchTerm ?: '').toLowerCase().trim()
def filtered = candidates.findAll { pr ->
    (termLower == '' || (pr.productName ?: '').toLowerCase().contains(termLower) || (pr.pseudoId ?: '').toLowerCase().contains(termLower)) &&
    (catProdIds == null || catProdIds.contains(pr.productId)) &&
    (pricingStatus != 'with' || (pr.mrpAmount != null && (pr.mrpAmount as BigDecimal) > 0G)) &&
    (pricingStatus != 'without' || pr.mrpAmount == null || (pr.mrpAmount as BigDecimal) <= 0G) &&
    (!gstFilter || (rateSlabOf(pr) != null && rateSlabOf(pr).stripTrailingZeros().toPlainString() == gstFilter))
}
// distinct GST rates present (for the 'More Filters' GST dropdown), ascending as plain strings.
distinctGstRates = candidates.collect { rateSlabOf(it) }.findAll { it != null }.unique().sort().collect { it.stripTrailingZeros().toPlainString() }
totalCount = filtered.size()
pageCount = (int) Math.ceil(totalCount / (double) pageSizeNum)
if (pageCount < 1) pageCount = 1
if (pIdx >= pageCount) pIdx = pageCount - 1
curPage = pIdx
def from = pIdx * pageSizeNum
def to = Math.min(from + pageSizeNum, totalCount)
def pageProds = (from < totalCount) ? filtered.subList(from, to) : []

// Fetch prices for all available modes on this page; toggling columns never discards drafts.
def pageIds = pageProds.collect { it.productId }
def modePriceMap = [:]; def wThr = [:]
if (pageIds) {
    ec.entity.find("zenith.erp.pos.PosProductModePrice").condition("productId", "in", pageIds).list().each { mp ->
        if (priceModeChoices.any { it.salesModeId == mp.salesModeId }) modePriceMap[mp.productId + ':' + mp.salesModeId] = mp.price
        if (mp.salesModeId == 'WHOLESALE') wThr[mp.productId] = mp.thresholdQty
    }
}
// Each product's GST rate (prices are GST-EXCLUSIVE -> the customer pays price + this %).
// Resolve the product's configured GST slab -> rate; blank if not GST-rated. (slabRates loaded above.)
def rateOf = { pr ->
    def sid = pr.gstSlabId
    if (!sid && (pr.hsnCode ?: pr.productTaxCode)) {
        try { sid = ec.entity.find("zenith.erp.india.IndiaHsnCode").condition("hsnCode", (pr.hsnCode ?: pr.productTaxCode)).one()?.defaultGstSlabId } catch (Exception ig) {}
    }
    (sid && slabRates[sid] != null) ? (slabRates[sid] as BigDecimal) : null
}
rows = pageProds.collect { pr ->
    def _r = rateOf(pr); def prices = [:]
    priceModeChoices.each { mode ->
        def override = modePriceMap[pr.productId + ':' + mode.salesModeId]
        def value = mode.priceSource == 'PpsFixedProduct' ? override : (override != null ? override : pr.mrpAmount)
        if (override == null && mode.priceSource == 'PpsDiscountMrp' && value != null) value = (value as BigDecimal) * (1G - ((mode.discountPercent ?: 0) as BigDecimal) / 100G)
        prices[mode.salesModeId] = value == null ? '' : (value as BigDecimal).setScale(2, java.math.RoundingMode.HALF_UP).stripTrailingZeros().toPlainString()
    }
    [productId:pr.productId, pseudoId:(pr.pseudoId ?: ''), productName:(pr.productName ?: pr.productId),
     modePrices:prices, wholesaleThreshold:(wThr[pr.productId] != null ? (wThr[pr.productId] as BigDecimal).stripTrailingZeros().toPlainString() : ''),
     gstRate:(_r != null ? _r.stripTrailingZeros().toPlainString() : '')]
}

// --- KPI aggregates for the stat cards (read-only; in-memory over the filtered set) ---
def _withPricing = filtered.count { it.mrpAmount != null && (it.mrpAmount as BigDecimal) > 0G }
def _gv = filtered.collect { pr -> (pr.gstSlabId && slabRates[pr.gstSlabId] != null) ? (slabRates[pr.gstSlabId] as BigDecimal) : null }.findAll { it != null }
totalDisp = String.format("%,d", (int) totalCount)
withDisp = String.format("%,d", (int) _withPricing)
withoutDisp = String.format("%,d", (int) (totalCount - _withPricing))
avgGstDisp = _gv ? (((_gv.sum() as BigDecimal) / _gv.size()).setScale(0, java.math.RoundingMode.HALF_UP)).toString() : ''
pageBase = curPage * pageSizeNum
selectedPageSize = pageSizeNum
showFrom = totalCount == 0 ? 0 : (pageBase + 1)
showTo = Math.min(pageBase + pageProds.size(), totalCount)
